harness.enable:
window.__genAltPrev = [];
const results = await axe.run({
  runOnly: { type: 'rule', values: Object.keys(m.axeHandlers) }
});
for (const violation of results.violations) {
  const handler = m.axeHandlers[violation.id];
  if (!handler) continue;
  for (const node of violation.nodes) {
    try {
      const el = document.querySelector(node.target[0]);
      if (!el || el.dataset.ai4a11yProcessed) continue;
      window.__genAltPrev.push({
        el,
        type: el.tagName.toLowerCase(),
        alt: el.getAttribute('alt'),
        hadAlt: el.hasAttribute('alt'),
        role: el.getAttribute('role'),
        hadRole: el.hasAttribute('role'),
        titleText: el.querySelector(':scope > title')?.textContent,
        hadTitle: !!el.querySelector(':scope > title'),
        processed: el.dataset.ai4a11yProcessed,
      });
      await handler(el);
    } catch (e) {
      console.error('Handler error:', e);
    }
  }
}

harness.disable:
if (window.__genAltPrev) {
  for (const item of window.__genAltPrev) {
    if (item.hadAlt) item.el.setAttribute('alt', item.alt);
    else item.el.removeAttribute('alt');
    if (item.hadRole) item.el.setAttribute('role', item.role);
    else item.el.removeAttribute('role');
    const titleEl = item.el.querySelector(':scope > title');
    if (item.hadTitle && titleEl) {
      titleEl.textContent = item.titleText;
    } else if (!item.hadTitle && titleEl) {
      titleEl.remove();
    }
    if (item.processed !== undefined) item.el.dataset.ai4a11yProcessed = item.processed;
    else delete item.el.dataset.ai4a11yProcessed;
  }
  delete window.__genAltPrev;
}

